-- Migration 0036 (spec 14.28): published passenger figures for the airports outside India.
--
-- What changes:
--  * 245 of the 340 airports outside India get their published passenger totals (pax_src V): FAA boardings x 2
--    for the USA (2025), Canada (2025), ACI Europe via Wikipedia (2024), the Middle East (2024), CAAC for mainland
--    China (2024), Africa (2025), Latin America and Mexico (2025). The other 95 stay estimates (pax_src G): Turkish,
--    Canary Islands and Larnaca airports, Saudi and Iraqi regional airports, Hong Kong and Macau, smaller African and
--    South American airports, and the destination-only airports in Asia and Oceania.
--  * Every market outside India (25,690) is rebuilt from the new figures by tools/build_regions.py (refresh): 25,683
--    markets. It refuses to run if any route flies a market outside India (none does: no world is based outside India).
--  * airports.seen_in is recomputed.
--  * India's 6,584 markets and 93 airports are not touched. No function changes.

