where a.iata = v.iata and not a.is_india;

do $$ begin
  if exists (select 1 from public.routes r join public.airports o on o.iata = r.origin join public.airports d on d.iata = r.dest
             where not o.is_india and not d.is_india) then
    raise exception 'A route flies a market outside India: rebuild it by hand';
  end if;
end $$;
delete from public.markets m where not exists (select 1 from public.airports x where x.iata in (m.a, m.b) and x.is_india);

